    /**
     * Tests creating a new Aircraft.
     *
     * @return    Aircraft
     */
    public Aircraft testCreate() throws Throwable {
    Aircraft entity = null;

    LOGGER.info( "AircraftTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Aircraft");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Aircraft" );

    try {
        entity = service.createAircraft( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getAircraftId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Aircraft with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

