    /**
     * Tests getting all Aircrafts.
     *
     * @return    Collection
     */
    public List<Aircraft> testGetAll() throws Throwable {
    LOGGER.info( "AircraftTest:testGetAll() - Retrieving Collection of Aircrafts:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Aircraft : " );
    List<Aircraft> collection  = null;

    try {
        // call the static get method on the AircraftService
        collection = service.getAllAircraft();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Aircraft currEntity  = null;
            Iterator<Aircraft> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getAircraftId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

